void UUS_CharacterMovementComponent::PerformQueuedPortalTraversal()
{
    AUS_Character* Character = Cast<AUS_Character>(CharacterOwner);
    if (!Character)
    {
        return;
    }

    // 死循环护栏：服务端已否决这一步（或更早的一步）的穿门主张，重放时不能再穿。
    const float MoveTimeStamp = GetCurrentMoveTimeStamp();
    if (MoveTimeStamp >= 0.f && MoveTimeStamp <= LastRejectedTraversalTimestamp)
    {
        return;
    }

    // 客户端不能指定穿哪扇门：两端都从角色胶囊当前位置独立查找。
    AUS_TrialPortal* Portal = AUS_TrialPortal::FindTraversablePortalFor(Character);
    // 服务端复核远程客户端的主张：它在本机严格落进了触发盒，服务端这一刻的位置可能差几厘米（从盒子最边缘踩入时），
    // 给一点容差再找一次，免得一次干净的预测穿门被拒绝、客户端闪过去又被拉回。
    if (!Portal && Character->HasAuthority() && !Character->IsLocallyControlled() && MoveTimeStamp >= 0.f)
    {
        Portal = AUS_TrialPortal::FindTraversablePortalFor(Character, USTrialPortal::ServerClaimTolerance);
        if (Portal)
        {
            UE_LOG(LogTrialPortalMove, Verbose, TEXT("%s: 服务端在 %.0f cm 容差内接受了边缘处的穿门主张"),
                *Character->GetName(), USTrialPortal::ServerClaimTolerance);
        }
    }
    if (!Portal)
    {
        UE_LOG(LogTrialPortalMove, Warning,
            TEXT("%s: 消费穿门标志时在 %s 处找不到可穿的门（门已失活？角色已走出触发盒？）"),
            *Character->GetName(), *Character->GetActorLocation().ToCompactString());

        // 服务端找不到合法的门 = 拒绝这一步的主张，通知客户端别再重放它。
        if (Character->HasAuthority() && !Character->IsLocallyControlled() && MoveTimeStamp >= 0.f)
        {
            Character->Client_RejectPortalTraversal(MoveTimeStamp, Character->GetControlRotation());
        }
        return;
    }

