namespace USMinionAlert
{
    /** 新的调查点能否落地。 */
    inline bool ShouldAcceptInvestigate(
        const EUS_AlertSource Incoming,
        const EUS_AlertSource Incumbent,
        const bool bLureActive,
        const bool bSightLockActive)
    {
        // 已过期的 T0 不再享有任何优先级。少了这一步，能力结束后若 Minion 一直
        // 没走到那个点，槽会被过期的 Lure **永久锁死**，噪声再也进不来。
        const EUS_AlertSource Effective =
            (Incumbent == EUS_AlertSource::Lure && !bLureActive)
                ? EUS_AlertSource::None
                : Incumbent;

        // T0 在位且未过期 → 只有 T0 能刷新它。
        if (Effective == EUS_AlertSource::Lure)
        {
            return Incoming == EUS_AlertSource::Lure;
        }
        // 视觉锁定期内噪声在**源头**被拒。写进去再让视觉清掉会让
        // Investigate/Chase 两个分支来回抢断 → MoveTo 重启抖动。
        if (Incoming == EUS_AlertSource::Noise && bSightLockActive)
        {
            return false;
        }
        return Incoming >= Effective || Effective == EUS_AlertSource::None;
    }

    /** 新的 TargetActor 能否落地（只裁"诱饵 vs 玩家"，其余仍由控制器的同值/新鲜度逻辑管）。 */
    inline bool ShouldAcceptTarget(
        const bool bIncomingIsPlayer,
        const bool bIncumbentIsLure,
        const bool bLureActive)
    {
        // GhostBook 这类漂移诱饵占着 TargetActor 时，视觉不许抢回来。
        return !(bIncomingIsPlayer && bIncumbentIsLure && bLureActive);
    }

    /** 看见玩家时是否清掉在位的调查点。 */
    inline bool ShouldClearInvestigateOnSight(const EUS_AlertSource Incumbent)
    {
        // 只清噪声点。清掉 T0 会让诱饵失去"压过视觉锁定"的能力，
        // 那正是当初把 Investigate 排在 Chase 之上的唯一理由。
        return Incumbent == EUS_AlertSource::Noise;
    }
}

