ERotateResult ApplyRotation(FUS_CoinLockState& State, uint8 Disc, int32 Steps)
{
    if ((Disc != DiscA && Disc != DiscB) || Steps == 0)
    {
        return ERotateResult::Invalid;
    }

    if (!CanDrive(State, Disc))
    {
        return ERotateResult::Seized;
    }

    // 咬合时另一枚反向同步数：A→惰轮1→惰轮2→B，两枚惰轮串联 ⇒ A 与 B 转向相反。
    const int32 Other = State.bClutchEngaged ? -Steps : 0;
    const int32 DeltaA = (Disc == DiscA) ? Steps : Other;
    const int32 DeltaB = (Disc == DiscB) ? Steps : Other;

    State.RotA = WrapPosition(static_cast<int32>(State.RotA) + DeltaA);
    State.RotB = WrapPosition(static_cast<int32>(State.RotB) + DeltaB);
    State.LastDriver = Disc;
    return ERotateResult::Rotated;
}

bool SetClutch(FUS_CoinLockState& State, bool bEngaged)
{
    if (State.bClutchEngaged == bEngaged)
    {
        return false;
    }
    State.bClutchEngaged = bEngaged;
    return true;
}

