namespace USRollingShelf
{
    /** Where the case is along its lane (0..1) at a server time. Linear in time; Ease() shapes it for the eye. */
    inline float ParamAt(const FUS_RollingShelfState& S, double Now, float TravelSeconds)
    {
        if (S.Phase != EUS_RollingShelfPhase::Moving) return FMath::Clamp(S.Param, 0.f, 1.f);
        const float Dir = S.TargetStop ? 1.f : -1.f;
        const float Step = float((Now - S.ServerTime) / FMath::Max(TravelSeconds, .1f));
        return FMath::Clamp(S.Param + Dir * FMath::Max(Step, 0.f), 0.f, 1.f);
    }

    /** Slow out of a stop, slow into a stop. Ease(0) = 0, Ease(1) = 1, never runs backwards. */
    inline float Ease(float P)
    {
        P = FMath::Clamp(P, 0.f, 1.f);
        return P * P * (3.f - 2.f * P);
    }

    inline bool HasArrived(const FUS_RollingShelfState& S, double Now, float TravelSeconds)
    {
        if (S.Phase != EUS_RollingShelfPhase::Moving) return false;
        const float P = ParamAt(S, Now, TravelSeconds);
        return S.TargetStop ? P >= 1.f : P <= 0.f;
    }

    /** The stop the case stands at, or -1 while it is on its way. */
    inline int32 RestStop(const FUS_RollingShelfState& S)
    {
        return S.Phase == EUS_RollingShelfPhase::Rest ? int32(S.TargetStop) : -1;
    }

    /** May the winch turn now? bBlocked: a body stands in the lane the case would sweep. */
    inline EUS_ShelfTurnRefusal CanTurn(const FUS_RollingShelfState& S, bool bBlocked)
    {
        if (S.Phase != EUS_RollingShelfPhase::Rest) return EUS_ShelfTurnRefusal::Moving;

