void AUS_GameState::MarkVictory(ACharacter* Winner)
{
    if (!HasAuthority()) return;
    if (Victory.bVictory) return;

    Victory.bVictory = true;
    Victory.Winner   = Winner;
    // 名字在服务端解析后随包携带：客户端即使胜者 actor channel 未就绪也能显示胜者名
    Victory.WinnerName.Empty();
    if (Winner)
    {
        if (const APlayerState* PS = Winner->GetPlayerState())
        {
            Victory.WinnerName = PS->GetPlayerName();
        }
    }

    // 服务端本端立即 fire（覆盖 listen-server host 的本地玩家）。
    // 远程客户端通过 OnRep_Victory 收到。OnRep 不会在 Authority 上触发，所以不会重复。
    OnVictory.Broadcast(Winner);
}

void AUS_GameState::OnRep_Victory()
{
    if (Victory.bVictory)
    {
        OnVictory.Broadcast(Victory.Winner);
    }
}

