void AUS_DecoyActor::Initialize(AUS_Character* InOwner, float InDuration, float InNoiseInterval,
    float InAttractionRadius, float InCaptureRadius)
{
    OwningPlayer = InOwner;
    Duration = FMath::Max(0.1f, InDuration);
    NoiseInterval = FMath::Max(0.1f, InNoiseInterval);
    AttractionRadius = FMath::Max(100.f, InAttractionRadius);
    CaptureRadius = FMath::Max(10.f, InCaptureRadius);
    CaptureCollision->SetSphereRadius(CaptureRadius, true);

    // 生命周期计时器必须放这里、不能放 BeginPlay：SpawnActor 会在返回前同步跑完 BeginPlay，
    // 那时 Duration 还是头文件默认值（旧 5.0）→ 用默认值起计时器会让诱饵提前自毁，而组件侧
    // DecoyExpireWorldTime 用的是真实 DecoyDuration（8）→ HUD 数到 3.0 时 actor 已销毁 → 瞬跳 0。
    // Initialize 在 SpawnActor 返回之后调用，此时 Duration 已是组件传入的正确值。
    if (HasAuthority())
    {
     const auto* GS=GetWorld()->GetGameState();HeadLureEndServerTime=(GS?GS->GetServerWorldTimeSeconds():GetWorld()->GetTimeSeconds())+Duration;
        GetWorldTimerManager().SetTimer(
            LifetimeTimerHandle, this, &AUS_DecoyActor::OnLifetimeExpired,
            Duration, false);
        GetWorldTimerManager().SetTimer(
            NoiseTimerHandle, this, &AUS_DecoyActor::EmitNoise,
            NoiseInterval, true, 0.0f);
    }
}

