bool AUS_TaskNPC::CanInteract_Implementation(AUS_Character* CharacterInstigator) const
{
    if (!CharacterInstigator)
    {
        return false;
    }

    // 有任务组件 → 完全交给组件裁定。组件基类默认仍卡 !bTaskCompleted；
    // Mage 谜题子类放开此门控，让"已解开/冷却中"也能交互 → 触发 NPC 对话。
    if (TaskComponent)
    {
        return TaskComponent->CanStartTask(CharacterInstigator);
    }

    return !bTaskCompleted;
}

