void UUS_AchievementSubsystem::LoadProgress()
{
    Progress.Reset();
    if (GetGameInstance() && GetGameInstance()->IsDedicatedServerInstance()) return;
    if (UUS_AchievementSaveGame* Save = Cast<UUS_AchievementSaveGame>(
        UGameplayStatics::LoadGameFromSlot(SaveSlotName, 0)))
    {
        if (Save->SaveVersion <= UUS_AchievementSaveGame::CurrentVersion)
        {
            Progress = Save->ProfileProgress;
        }
    }
}

void UUS_AchievementSubsystem::SaveProgress()
{
    if (GetGameInstance() && GetGameInstance()->IsDedicatedServerInstance()) return;
    UUS_AchievementSaveGame* Save = Cast<UUS_AchievementSaveGame>(
        UGameplayStatics::CreateSaveGameObject(UUS_AchievementSaveGame::StaticClass()));
    if (!Save) return;

    Save->SaveVersion = UUS_AchievementSaveGame::CurrentVersion;
    for (const UUS_AchievementDefinition* Definition : Definitions)
    {
        if (!Definition || Definition->Scope != EUS_AchievementScope::Profile) continue;
        if (const FUS_AchievementProgress* State = Progress.Find(Definition->AchievementId))
        {
            Save->ProfileProgress.Add(Definition->AchievementId, *State);
        }
    }
    if (UGameplayStatics::SaveGameToSlot(Save, SaveSlotName, 0)) bProfileDirty = false;
}

